92	const buildDirectedAdjacency = (
93	  nodes: G6NodeData[],
94	  edges: G6EdgeData[]
95	): { forward: Map<string, string[]>; backward: Map<string, string[]> } => {
96	  const forward = new Map<string, string[]>();
97	  const backward = new Map<string, string[]>();
98	  nodes.forEach((n) => {
99	    forward.set(n.id, []);
100	    backward.set(n.id, []);
101	  });
102	  edges.forEach((e) => {
103	    forward.get(String(e.source))?.push(String(e.target));
104	    backward.get(String(e.target))?.push(String(e.source));
105	  });
106	
107	  return { forward, backward };
108	};
