110	const bfsFromNode = (
111	  adj: Map<string, string[]>,
112	  startId: string
113	): Map<string, number> => {
114	  const depth = new Map<string, number>();
115	  depth.set(startId, 0);
116	  const queue = [startId];
117	  let qi = 0;
118	  while (qi < queue.length) {
119	    const cur = queue[qi++];
120	    const d = depth.get(cur)!;
121	    for (const nbr of adj.get(cur) ?? []) {
122	      if (!depth.has(nbr)) {
123	        depth.set(nbr, d + 1);
124	        queue.push(nbr);
125	      }
126	    }
127	  }
128	
129	  return depth;
130	};
