132	const computeDirectedBFSPartitions = (
133	  nodes: G6NodeData[],
134	  edges: G6EdgeData[],
135	  focusNodeId: string
136	): Map<string, number> => {
137	  const { forward, backward } = buildDirectedAdjacency(nodes, edges);
138	  const backDepth = bfsFromNode(backward, focusNodeId);
139	  const fwdDepth = bfsFromNode(forward, focusNodeId);
140	
141	  let maxBack = 0;
142	  backDepth.forEach((d) => {
143	    if (d > maxBack) {
144	      maxBack = d;
145	    }
146	  });
147	
148	  const partitions = new Map<string, number>();
149	  partitions.set(focusNodeId, maxBack);
150	  // Pure predecessors only — nodes reachable in both directions participate in
151	  // cycles or cross-paths; assigning them a partition would create backward edges
152	  // in ELK's layer graph, causing a negative-index crash.
153	  backDepth.forEach((d, id) => {
154	    if (id !== focusNodeId && !fwdDepth.has(id)) {
155	      partitions.set(id, maxBack - d);
156	    }
157	  });
158	  fwdDepth.forEach((d, id) => {
159	    if (id !== focusNodeId && !backDepth.has(id)) {
160	      partitions.set(id, maxBack + d);
161	    }
162	  });
163	
164	  return partitions;
165	};
